/**
 * Webhook endpoints and their delivery attempts.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, webhookDeliveries, webhookEndpoints } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { CreateWebhookInput, UpdateWebhookInput } from "@/schemas/webhook";
import type {
  WebhookDeliveryRow,
  WebhookEndpointRow,
} from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, WebhookId } from "@/types/common";

export async function listEndpoints(
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  return getDb()
    .select()
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .orderBy(asc(webhookEndpoints.createdAt))
    .all();
}

export async function insertEndpoint(
  input: CreateWebhookInput,
  secret: string,
): Promise<WebhookEndpointRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookEndpoints)
    .values({
      id: newId(),
      orgId: input.orgId,
      url: input.url,
      secret,
      eventTypes: JSON.stringify(input.eventTypes),
      enabled: true,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

export async function updateEndpoint(
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  const row = getDb()
    .update(webhookEndpoints)
    .set({
      ...(input.url === undefined ? {} : { url: input.url }),
      ...(input.eventTypes === undefined
        ? {}
        : { eventTypes: JSON.stringify(input.eventTypes) }),
      ...(input.enabled && { enabled: input.enabled }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, input.orgId),
        eq(webhookEndpoints.id, input.webhookId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);
  return row;
}

export async function deleteEndpoint(
  orgId: OrgId,
  webhookId: WebhookId,
): Promise<void> {
  const db = getDb();
  db.delete(webhookDeliveries)
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.endpointId, webhookId),
      ),
    )
    .run();
  db.delete(webhookEndpoints)
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, orgId),
        eq(webhookEndpoints.id, webhookId),
      ),
    )
    .run();
}

/** The `webhooks` quota compares against this. */
export async function countEndpoints(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function enqueueDelivery(
  orgId: OrgId,
  endpointId: string,
  eventType: string,
  payload: string,
): Promise<WebhookDeliveryRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

/**
 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
 * drained by a background worker, not by a request — and the attempt counter
 * is bumped on claim so a crashed worker cannot retry forever.
 */
export async function claimPendingDeliveries(
  limit: number,
): Promise<readonly WebhookDeliveryRow[]> {
  const db = getDb();
  const pending = db
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.status, "pending"))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

export async function markDelivered(
  orgId: OrgId,
  deliveryId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({ status: "delivered", deliveredAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

export async function markDeliveryFailed(
  orgId: OrgId,
  deliveryId: string,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const webhookEndpoints = sqliteTable(
  "webhook_endpoints",
  {
    id: idColumn(),
    ...tenantColumns,
    url: text("url").notNull(),
    secret: text("secret").notNull(),
    /** JSON array of `TaskflowEventType`. */
    eventTypes: text("event_types").notNull().default("[]"),
    enabled: integer("enabled", { mode: "boolean" }).notNull().default(true),
    ...timestampColumns,
  },
  (table) => [index("webhook_endpoints_org_idx").on(table.orgId)],
);

export const webhookDeliveries = sqliteTable(
  "webhook_deliveries",
  {
    id: idColumn(),
    ...tenantColumns,
    endpointId: text("endpoint_id").notNull(),
    eventType: text("event_type").notNull(),
    payload: text("payload").notNull(),
    status: text("status", { enum: ["pending", "delivered", "failed"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastError: text("last_error"),
    deliveredAt: text("delivered_at"),
    ...timestampColumns,
  },
  (table) => [
    index("webhook_deliveries_org_status_idx").on(table.orgId, table.status),
  ],
);

/** Token-bucket state for `src/lib/rate-limit.ts`, persisted per org+key. */
export const rateLimitBuckets = sqliteTable(
  "rate_limit_buckets",
  {
    id: idColumn(),
    ...tenantColumns,
    bucketKey: text("bucket_key").notNull(),
    tokens: integer("tokens").notNull(),
    refilledAt: text("refilled_at").notNull(),
  },
  (table) => [index("rate_limit_org_key_idx").on(table.orgId, table.bucketKey)],
);

/** Denormalised full-text index maintained by `SearchService`. */
export const searchIndex = sqliteTable(
  "search_index",
  {
    id: idColumn(),
    ...tenantColumns,
    subjectKind: text("subject_kind", {
      enum: ["issue", "comment", "project"],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    content: text("content").notNull(),
    indexedAt: text("indexed_at").notNull(),
  },
  (table) => [
    index("search_index_org_kind_idx").on(table.orgId, table.subjectKind),
  ],
);

export type WebhookEndpointRow = typeof webhookEndpoints.$inferSelect;
export type WebhookDeliveryRow = typeof webhookDeliveries.$inferSelect;
export type SearchIndexRow = typeof searchIndex.$inferSelect;
/**
 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
 *
 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
 */
import { getPlanLimits } from "@/config/plan-limits";
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { signPayload } from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** How many deliveries one pass claims. */
const CLAIM_BATCH = 25;

/** Attempts after which a delivery is marked failed for good. */
const MAX_ATTEMPTS = 6;

const logger = createLogger("webhook-delivery-job");

/**
 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
 * corpus builds and runs offline — so "delivery" means computing the
 * signature the receiver would verify and logging the attempt. The retry
 * bookkeeping around it is the part that has to be right.
 */
export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
  return runJob("webhook-delivery", async (result) => {
    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);

    for (const delivery of claimed) {
      const orgId = delivery.orgId as OrgId;

      if (!(await orgAllowsWebhooks(orgId))) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "webhooks are not included in this organization's plan",
        );
        result.failed += 1;
        continue;
      }

      if (delivery.attempts > MAX_ATTEMPTS) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          `giving up after ${delivery.attempts} attempts`,
        );
        result.failed += 1;
        continue;
      }

      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
        (row) => row.id === delivery.endpointId,
      );

      if (!endpoint) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "endpoint no longer exists",
        );
        result.failed += 1;
        continue;
      }

      const signature = signPayload(endpoint.secret, delivery.payload);

      logger.info("webhook delivered", {
        deliveryId: delivery.id,
        endpoint: endpoint.url,
        eventType: delivery.eventType,
        signature: signature.slice(0, 16),
        backoffMs: backoffMs(delivery.attempts),
      });

      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
      result.processed += 1;
    }
  });
}

/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
export function backoffMs(attempts: number): number {
  if (attempts <= 0) return 0;
  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
}

async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return false;

  if (getPlanLimits(org.plan).webhooks <= 0) return false;
  return isEnabled("webhooks", buildFlagContext(null, org));
}
